          ], { align: AlignmentType.CENTER, spacing: { before: 0, after: 0 } })
        ]
      })
    },
    children: [

      // ── TITLE ──────────────────────────────────────────────────
      ...blank(2),
      para([t('Cold Fusion Host Identification via the', { bold: true, size: 36 })],
