const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  PageNumber, Footer, PageBreak, Table, TableRow, TableCell, WidthType,
  BorderStyle, ShadingType, ImageRun, convertInchesToTwip, TableOfContents
} = require('docx');
const fs = require('fs');

const F = 'Cambria', M = 'Consolas';
const S = 21, SM = 17, H1 = 30, H2 = 25, H3 = 22;

function t(x, o = {}) {
  return new TextRun({ text: x, font: o.mono ? M : F, size: o.size || S,
    bold: !!o.bold, italics: !!o.italic, color: o.color, superScript: o.sup, subScript: o.sub });
}
function p(runs, o = {}) {
  return new Paragraph({
    children: Array.isArray(runs) ? runs : [runs],
    spacing: o.spacing || { before: 120, after: 60, line: 276 },
    alignment: o.align || AlignmentType.JUSTIFIED,
    indent: o.indent, heading: o.heading, pageBreakBefore: !!o.pb,
    border: o.border
  });
}
const h1 = (x, pb) => p([t(x, { bold: true, size: H1 })],
  { spacing: { before: 360, after: 160 }, heading: HeadingLevel.HEADING_1, align: AlignmentType.LEFT, pb });
const h2 = (x) => p([t(x, { bold: true, size: H2 })],
  { spacing: { before: 280, after: 120 }, heading: HeadingLevel.HEADING_2, align: AlignmentType.LEFT });
const h3 = (x) => p([t(x, { bold: true, italic: true, size: H3 })],
  { spacing: { before: 200, after: 100 }, heading: HeadingLevel.HEADING_3, align: AlignmentType.LEFT });

function eq(x, num) {
  const kids = [t('      '), t(x, { mono: true, size: S })];
  if (num) kids.push(t('          (' + num + ')', { size: SM }));
  return p(kids, { align: AlignmentType.LEFT, spacing: { before: 140, after: 140 } });
}
function img(file, w, h) {
  return new Paragraph({
    children: [new ImageRun({ data: fs.readFileSync(file), transformation: { width: w, height: h }, type: 'png' })],
    alignment: AlignmentType.CENTER, spacing: { before: 200, after: 80 }
  });
}
function cap(n, txt) {
  return p([t(`Figure ${n}. `, { bold: true, size: SM }), t(txt, { size: SM })],
    { spacing: { before: 0, after: 220 }, align: AlignmentType.JUSTIFIED,
      indent: { left: convertInchesToTwip(0.35), right: convertInchesToTwip(0.35) } });
}
function tcap(n, txt) {
  return p([t(`Table ${n}. `, { bold: true, size: SM }), t(txt, { size: SM })],
    { spacing: { before: 140, after: 80 }, align: AlignmentType.LEFT });
}
function rule() {
  return p([t('')], { spacing: { before: 60, after: 60 },
    border: { bottom: { color: '999999', style: BorderStyle.SINGLE, size: 6 } } });
}
function cell(x, w, o = {}) {
  return new TableCell({
    children: [p([t(x, { size: SM, bold: o.bold, color: o.color })],
      { align: o.align || AlignmentType.CENTER, spacing: { before: 40, after: 40 } })],
    width: { size: w, type: WidthType.DXA },
    shading: o.fill ? { type: ShadingType.CLEAR, fill: o.fill } : undefined
  });
}
function table(headers, rows, widths, hi = []) {
  const hr = new TableRow({ children: headers.map((x, i) => cell(x, widths[i], { bold: true, fill: 'DCD8D0' })) });
  const drs = rows.map(r => new TableRow({
    children: r.map((x, i) => cell(String(x), widths[i], { fill: hi.includes(r[1]) ? 'EAF3EC' : undefined }))
  }));
  return new Table({ rows: [hr, ...drs], width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA }, columnWidths: widths });
}

const B = [];  // body

// ══════════════════ TITLE ══════════════════
B.push(p([t('')], { spacing: { before: 900, after: 0 } }));
B.push(p([t('The Lach Elemental Field Equation Theorem', { bold: true, size: 40 })], { align: AlignmentType.CENTER, spacing: { after: 100 } }));
B.push(p([t('A Three-Dimensional Configuration-Space Framework for the', { size: 24 })], { align: AlignmentType.CENTER, spacing: { after: 40 } }));
B.push(p([t('Organisation of the Chemical Elements', { size: 24 })], { align: AlignmentType.CENTER, spacing: { after: 300 } }));
B.push(rule());
B.push(p([t('with', { italic: true, size: 22 })], { align: AlignmentType.CENTER, spacing: { before: 160, after: 60 } }));
B.push(p([t('Part II — An Exploratory Application to Deuteride Host Selection', { bold: true, size: 26 })], { align: AlignmentType.CENTER, spacing: { after: 320 } }));
B.push(p([t('Matthew Lach', { size: 24 })], { align: AlignmentType.CENTER, spacing: { after: 40 } }));
B.push(p([t('with computational assistance from Claude (Anthropic)', { italic: true, size: 19, color: '555555' })], { align: AlignmentType.CENTER, spacing: { after: 200 } }));
B.push(p([t('2026', { size: 21, color: '666666' })], { align: AlignmentType.CENTER, spacing: { after: 400 } }));

B.push(p([t('Abstract', { bold: true, size: 23 })], { align: AlignmentType.LEFT, spacing: { before: 200, after: 100 } }));
B.push(p([t('Part I develops a three-axis lattice in which every element occupies a coordinate (n, ℓ, k) defined by the quantum numbers of its ground-state valence configuration. All 118 known elements are placed; the surrounding empty volume is classified as void (ℓ ≥ n, orbital non-existent), reactive (k exceeds Pauli capacity), or reserved (valid but unoccupied). A census of the 7 × 5 × 18 lattice gives 180 void, 240 reactive, 92 reserved and 118 occupied cells. A time-dependent expression Ψ±Z(t) is derived describing each element as a three-state system oscillating between its ground configuration and its two nearest excited neighbours, and the displacement vector ΔQ is shown to sort the elements into three geometric classes. The principal structural result is that the lattice makes visible an adjacency the conventional two-dimensional table conceals: the late f-block and the late 5d metals occupy neighbouring regions of configuration space, whereas the standard layout exiles the lanthanides to a detached strip.')]));
B.push(p([t('Part II applies that adjacency to a concrete question — which metals might be worth testing as deuteride hosts — and reports the attempt honestly, including its failure to produce a physical prediction. A heuristic index H_cp is constructed from the lattice coordinates and combined with a crystal-structure filter to screen all 118 elements down to a short candidate list. Ytterbium emerges as the notable entry: an FCC hydride-former with the largest configuration-space distance of any viable candidate, and one that appears untested in the deuteride-loading literature. We then set out plainly why this ordering is not a falsifiable prediction. The candidate ranking is shown to depend on which of several defensible screening conventions is adopted, and the framework produces dimensionless ratios that cannot be converted into tunnelling rates without importing an unconstrained external scale. Part II is therefore offered as a candidate-generation heuristic, not a theory of low-energy nuclear reactions.')]));

B.push(new Paragraph({ children: [new PageBreak()] }));

// ══════════════════ PART I ══════════════════
B.push(h1('PART I — THE CONFIGURATION-SPACE LATTICE'));

B.push(h2('1.  Introduction'));
B.push(p([t('Mendeleev\'s table remains the most productive organising device in chemistry, and its two-dimensional form encodes real periodicity: rows track the principal quantum number, columns track valence behaviour. But the layout imposes compromises that are cartographic rather than physical. The f-block is removed from the body of the table and printed below it, for reasons of page width alone. Subshell type ℓ and occupancy k are conflated into a single positional axis, so two elements in one group may share electron count while occupying different subshells. And the table has no vocabulary for absence: a gap either holds an undiscovered element or is nothing at all, with no way to say which vacancies are physically possible and which are forbidden.')]));
B.push(p([t('This paper treats n, ℓ and k as three independent axes and asks what becomes visible. The construction is deliberately minimal — no new physics is introduced, only a change of coordinates. What the change buys is set out in Sections 2 through 5: a classification of empty space, a geometric sorting of the elements into three classes, and an adjacency relation that the conventional layout destroys.')]));

B.push(h2('2.  Construction of the Lattice'));
B.push(p([t('Each element is assigned the coordinate (n, ℓ, k) of its ground-state valence configuration, where n is the principal quantum number, ℓ ∈ {0,1,2,3,4} denotes s, p, d, f, g, and k counts the electrons occupying that subshell. The admissible lattice is')]));
B.push(eq('Λ = { (n, ℓ, k) ∈ ℤ³ : 0 ≤ ℓ ≤ n−1,  1 ≤ k ≤ 2(2ℓ+1) }', '1'));
B.push(p([t('the two constraints being the angular-momentum condition and the Pauli capacity of the subshell. Hydrogen anchors the origin at (1, 0, 1). A fifth layer at ℓ = 4 is carried as a theoretical extension; no known ground state occupies it.')]));
B.push(p([t('Two features of this construction deserve emphasis, because they will matter in Part II. First, the axes are quantum numbers, not lengths — n indexes a shell, ℓ indexes angular momentum, k is a count. Distances in the lattice are therefore combinatorial, not metric. Second, the axes are coupled: the range of ℓ depends on the value of n, and the range of k depends on ℓ. The lattice is a bounded, interdependent integer structure, and this is precisely what allows the classification in Section 3.')]));

B.push(h2('3.  The Classification of Empty Space'));
B.push(p([t('Every cell not occupied by a known element falls into exactly one of three regimes, and the distinction is the first substantive product of the coordinate change.')]));
B.push(p([t('Void cells satisfy ℓ ≥ n. The orbital does not exist for that shell, and no element can ever occupy the cell under any conditions. Reactive cells satisfy ℓ < n but k > 2(2ℓ+1): the electron count exceeds Pauli capacity, so the configuration cannot be a ground state; under the reading proposed here these correspond to transient overflow states in which the excess electron is promoted to a new shell. Reserved cells satisfy both constraints yet hold no known element. These are valid, physically permitted configurations that are simply unoccupied.')]));
B.push(p([t('A full census of the 7 × 5 × 18 lattice is given in Figure 1. Of 630 cells, 180 are void, 240 reactive, 92 reserved, and 118 occupied. The reserved count corrects the figure of 78 quoted in the earlier draft of this work; the recount is exact and is reproduced by the classification code accompanying this paper.')]));
B.push(img('fig1_cells.png', 600, 250));
B.push(cap(1, 'Census of the configuration-space lattice. (a) The 630 cells partition into four regimes, with the void and reactive classes together accounting for two-thirds of the volume. (b) Distribution of the 92 reserved cells across (n, ℓ). Reserved cells concentrate at n = 6–7 in the d, f and g layers — the region corresponding to elements beyond Z = 118.'));
B.push(p([t('The concentration visible in Figure 1(b) is the point. Reserved cells are not scattered uniformly through the empty volume; 42 of the 92 sit at n = 7 and a further 32 at n = 6, overwhelmingly in the higher-ℓ layers. In the two-dimensional table this region is simply the blank space past oganesson. Here it is a set of addressed coordinates, each with a defined neighbourhood.')]));

B.push(h2('4.  The Elements in Place'));
B.push(p([t('Figure 2 shows all 118 elements at their ground-state coordinates. No manual grouping is applied: the block structure emerges from the ℓ-axis alone, and within each block the elements stratify along n by period. The f-block, which the conventional table detaches entirely, sits in the body of the structure at ℓ = 3.')]));
B.push(img('fig2_lattice3d.png', 620, 282));
B.push(cap(2, 'The 118 known elements at their ground-state coordinates (n, ℓ, k). Colour denotes block; the gold ring marks hydrogen at the origin (1, 0, 1). (a) Oblique view. (b) Near-edge view showing the clean separation of blocks along the ℓ-axis. The clustering is a consequence of the coordinates, not of any imposed arrangement.'));

B.push(h2('5.  Excited Neighbourhoods and the Field Equation'));
B.push(p([t('Each element is modelled as a three-state system: its ground configuration Q₀ = (n, ℓ, k) together with its two nearest excited neighbours,')]));
B.push(eq('Q₁ = (n+1, ℓ, k)      [shell excitation]', '2'));
B.push(eq('Q₂ = (n, ℓ±1, k)      [subshell excitation]', '3'));
B.push(p([t('with Q₂ taking ℓ+1 where the angular-momentum condition permits and ℓ−1 otherwise. Writing the state as a superposition over the accessible cells and requiring normalisation at all t, ground-state occupancy at t = 0, and sinusoidal evolution at base frequency Ω gives coefficients c₀ = cos(Ωt) and c₁ = c₂ = sin(Ωt)/√2. The expectation position ⟨Q⟩(t) then traces a bounded path through configuration space, and the variance σ²(t) measures the instantaneous spread. Phase-shifting the coefficients by π/2 yields the inverse (emission) expression, and combining the two gives the unified form')]));
B.push(eq('Ψ±Z(t) = √2 · sin(Ωt + π/4) · Σ(n,ℓ,k)∈Λ |n, ℓ, k⟩', '4'));
B.push(p([t('The displacement from the midpoint of the excited pair back to the ground state,')]));
B.push(eq('ΔQ = Q₀ − ½(Q₁ + Q₂)', '5'));
B.push(p([t('is a static vector characterising the geometry of each element\'s neighbourhood, and the interaction term S_Z(t) = cos(2Ωt) · ΔQ oscillates at twice the base frequency.')]));
B.push(p([t('A caution on interpretation. Equation (4) is a construction on the lattice, not a solution of a Hamiltonian derived from physical potentials. Ω is a formal parameter; nothing in this paper establishes a correspondence between Ω and a measurable frequency in any material. The expression is best read as a compact description of how each element\'s accessible configurations are arranged around it, and the results that follow depend only on the geometry of ΔQ, not on any dynamical claim.')]));

B.push(h2('6.  Three Geometric Classes'));
B.push(p([t('Evaluating ΔQ across all 118 elements yields a sharply degenerate result. The magnitude |ΔQ| takes exactly two values: unity for hydrogen and helium, and 1/√2 for every other element. The elements are differentiated not by the size of the displacement but by its direction, which falls into three cases.')]));
B.push(p([t('Class A comprises hydrogen and helium alone. Here n = 1 admits only ℓ = 0, so both excited neighbours collapse onto the same cell, Q₁ = Q₂. The neighbourhood is one-dimensional and the spread at maximum excitation vanishes.')]));
B.push(p([t('Class B comprises elements for which ℓ+1 ≤ n−1, so subshell excitation moves toward higher angular momentum. Class C comprises elements for which only ℓ−1 is available, so subshell excitation moves toward lower angular momentum. Figure 3 shows the membership.')]));
B.push(img('fig3_classes.png', 600, 229));
B.push(cap(3, 'Direction classes of the displacement vector ΔQ. (a) Schematic of the three cases. (b) Class membership across atomic number. The 3d series and the lanthanides fall in Class C; the 4d and 5d series fall in Class B. The classification follows entirely from the angular-momentum constraint ℓ ≤ n−1 and requires no additional input.'));
B.push(p([t('The classification is not arbitrary bookkeeping. It states which direction in configuration space each element\'s accessible excitations lie, and it separates the 3d and 4f series from the 4d and 5d series on purely geometric grounds.')]));

B.push(h2('7.  The Adjacency Result'));
B.push(p([t('The most consequential structural finding is illustrated in Figure 4. Consider ytterbium, (4, 3, 13), and platinum, (5, 2, 8). In the conventional table these elements are maximally separated by the layout: Yb sits in the detached lanthanide strip printed beneath the body of the table, Pt sits in period 6 of the main block. Nothing in the printed arrangement suggests any relationship between them.')]));
B.push(p([t('In the lattice they are close. Both occupy the high-k region of the high-ℓ layers, separated by one step in ℓ and a few in k, and both sit at large configuration-space distance from the origin — |Q₀| = 13.93 for Yb and 9.64 for Pt, against 9.17 for palladium. The late f-block and the late 5d metals form a contiguous region that the two-dimensional layout tears in half.')]));
B.push(img('fig4_adjacency.png', 640, 245));
B.push(cap(4, 'The adjacency the conventional layout conceals. (a) In the standard table, ytterbium is displaced into the lanthanide strip, far from platinum; the dashed arc indicates the separation imposed by the layout. (b) In the (ℓ, k) projection of the lattice, Yb and Pt are neighbours within a contiguous high-|Q₀| region. Marker size encodes n. This adjacency is the principal structural result of Part I and the point of departure for Part II.'));

B.push(h2('8.  Reserved Cells and Undiscovered Elements'));
B.push(p([t('The 92 reserved cells are addressed vacancies: each carries coordinates, a defined excited neighbourhood via Equations (2) and (3), and hence a computable ΔQ. Their concentration at n = 6–7 in the d, f and g layers corresponds to the region beyond Z = 118, and the framework therefore offers a geometric description of where a superheavy element would sit and what its configuration-space neighbourhood would look like.')]));
B.push(p([t('It is worth being precise about what this does and does not amount to. The lattice states that certain configurations are permitted and unoccupied. It does not predict nuclear stability, synthesis cross-sections, or half-lives, all of which are governed by nuclear structure rather than valence configuration. The reserved-cell analysis constrains where to look in configuration space; it says nothing about whether a nucleus placed there would survive long enough to be observed. Claims in the earlier draft that the framework transforms the search for new elements into a bounded problem overstate this, and are withdrawn.')]));

B.push(h2('9.  Relationship to Existing Frameworks'));
B.push(p([t('Alternative periodic arrangements have a long history — helical, cylindrical, pyramidal and left-step forms among them. These generally reorganise by atomic number and chemical periodicity while preserving a two-dimensional surface. The present construction differs in treating the three quantum numbers as independent geometric axes and, more importantly, in classifying the resulting empty volume into physically distinguished regimes. The mathematical ingredients — bra-ket notation, superposition, the Pauli principle — are entirely standard; what is offered here is a coordinate choice and the structural facts it reveals.')]));

B.push(new Paragraph({ children: [new PageBreak()] }));

// ══════════════════ PART II ══════════════════
B.push(h1('PART II — AN EXPLORATORY APPLICATION TO DEUTERIDE HOST SELECTION'));

B.push(p([t('Prefatory note. ', { bold: true }), t('This part is exploratory. It records an attempt to apply the lattice to the selection of metal hosts for deuterium loading, and reports both what the attempt produced and where it failed. The failure is instructive and is set out in full in Sections 13 and 14. Readers interested only in established results should treat Part I as self-contained; Part II makes no claim to constitute a theory of low-energy nuclear reactions, and its ranking should not be read as a physical prediction.')], { spacing: { before: 160, after: 200 } }));

B.push(h2('10.  Motivation'));
B.push(p([t('The 1989 Fleischmann–Pons experiments used palladium, and palladium has dominated the subsequent literature. The choice was reasonable on practical grounds — Pd absorbs hydrogen readily, is workable, is not toxic, and was available. It was not the product of a search over host materials guided by any structural principle, because no such principle was available.')]));
B.push(p([t('The adjacency result of Section 7 suggests one possible line of attack. If the late f-block and late 5d metals form a coherent region in configuration space, and palladium sits at the edge of that region rather than within it, then the lattice identifies neighbouring elements that a Pd-centred literature would not naturally have reached. The question this part asks is narrow: does the lattice generate a candidate list worth attention?')]));

B.push(h2('11.  A Heuristic Index'));
B.push(p([t('We construct an index intended to capture two intuitions: that an element deep in configuration space presents a more complex electronic environment at interstitial sites, and that higher-ℓ subshells contribute more interstitial density at appreciable filling. The index is')]));
B.push(eq('H_cp(n, ℓ, k) = √(n² + ℓ² + k²) · ( k / 2(2ℓ+1) )^(ℓ/4)', '6'));
B.push(p([t('The first factor is the configuration-space distance |Q₀|. The second is the fractional subshell filling raised to a power that increases with ℓ, the exponent ℓ/4 being normalised by the lattice ceiling ℓ_max = 4.')]));
B.push(p([t('This expression is a choice, and we flag it as such rather than presenting it as derived. Infinitely many monotonic functions of ℓ and k satisfy the stated intuitions; ℓ/4 was selected for its normalisation against the lattice ceiling and because it is the simplest such form, not because the framework requires it. A different exponent gives a different index and, as Section 13 shows, a different ordering. The index has no dimensions and no interpretation as a rate, an energy, or a probability. It is a sorting device.')]));

B.push(h2('12.  The Screen'));
B.push(p([t('Two filters are applied to all 118 elements. The first is chemical: the host must form a well-characterised interstitial hydride or deuteride, since a metal that does not absorb deuterium cannot serve as a loading matrix. The second is structural. In an FCC lattice the octahedral interstitial sites are all equivalent by symmetry and occur six to the unit cell, so three deuterons can occupy translationally equivalent positions. In HCP the octahedral sites are not all equivalent and the geometry depends on the c/a ratio; in DHCP the layer alternation breaks equivalence outright. FCC is therefore taken as the permissive case.')]));
B.push(p([t('Neither filter derives from the lattice. Both are ordinary crystallography, imported. The lattice contributes only the index by which the surviving candidates are sorted.')]));
B.push(img('fig5_screen.png', 620, 232));
B.push(cap(5, 'Screening across the elements. (a) Configuration-space distance |Q₀| against atomic number, with elements passing both filters ringed. The three labelled entries are Pd (the historical host), Pt and Yb. (b) The two-filter funnel: 118 elements reduce to nine candidates.'));

B.push(tcap(1, 'Candidates passing both filters, ordered by the heuristic index. Ranking is convention-dependent — see Section 13 and Figure 6.'));
B.push(table(
  ['Rank', 'El.', '(n, ℓ, k)', '|Q₀|', 'H_cp', 'Class', 'Note'],
  [
    ['1', 'Yb', '(4, 3, 13)', '13.93', '13.18', 'C', 'apparently untested'],
    ['2', 'Au', '(5, 2, 9)', '10.49', '9.95', 'B', 'poor absorber'],
    ['3', 'Ag', '(4, 2, 9)', '10.05', '9.53', 'B', 'weak absorber'],
    ['4', 'Pt', '(5, 2, 8)', '9.64', '8.63', 'B', 'well studied'],
    ['5', 'Pd', '(4, 2, 8)', '9.17', '8.20', 'B', 'historical host'],
    ['6', 'Ni', '(3, 2, 8)', '8.78', '7.85', 'C', 'well studied'],
    ['7', 'Ir', '(5, 2, 7)', '8.83', '7.39', 'B', 'little studied'],
    ['8', 'Rh', '(4, 2, 7)', '8.31', '6.95', 'B', 'little studied'],
    ['9', 'Th', '(5, 3, 1)', '5.92', '0.82', 'B', 'radioactive'],
  ],
  [700, 700, 1500, 900, 900, 900, 2200],
  ['Yb']
));

B.push(p([t('The entry that stands out is ytterbium. It has the largest configuration-space distance of any candidate, it forms YbH₂ and YbH₃ under accessible conditions, it adopts an FCC structure, it is stable and commercially available — and a survey of the deuteride-loading literature turns up no report of its use as a primary host. Whatever the status of the index that ranked it, the observation that a chemically suitable, structurally suitable, commercially available metal appears never to have been tried is independent of the index and stands on its own.')], { spacing: { before: 160, after: 120 } }));

B.push(h2('13.  Why the Ordering Is Not a Prediction'));
B.push(p([t('Table 1 sorts by H_cp alone. But the screen involves further modelling choices, and it is instructive to see what happens when they are varied within the range of defensible options.')]));
B.push(p([t('A phase term may be introduced to represent the geometric relationship between occupied interstitial sites, requiring a lattice parameter. That parameter can be taken from measurement, or estimated from the lattice via a screening model — Slater\'s rules, or Clementi–Raimondi values, applied either to the valence orbital or to the bonding orbital. Each of these is a reasonable choice. Each yields a different ordering.')]));
B.push(img('fig6_convention.png', 520, 288));
B.push(cap(6, 'Candidate ordering under three modelling conventions. Ytterbium (green) ranks first under two conventions and fourth under the third; palladium (amber) moves between third and fifth. Because the ordering is not stable across defensible choices, it is a property of the convention adopted rather than a result derived from the lattice.'));
B.push(p([t('This is decisive, and we state the conclusion plainly. Yb ranks first under two conventions and fourth under a third; Pt ranks fourth, sixth and eighth. When a result depends on which of several equally justifiable conventions the analyst adopts, that result characterises the analyst\'s choice and not the structure under study. The ordering in Table 1 is therefore reported as one convention\'s output, not as a prediction of the framework.')]));
B.push(p([t('We note also, for the record, that two intermediate steps in the exploratory work were initially presented as derivations and were not. An interaction term of the form γ·Q̂⊗Q̂ was described as the natural coupling; it is one choice among many, and alternatives give different functional forms downstream. The exponent ℓ/4 in Equation (6) was described as the unique form satisfying the stated constraints; it is not unique, and it was selected after the index it appears in had already been written down. Both are recorded here as choices.')]));

B.push(h2('14.  The Dimensional Obstruction'));
B.push(p([t('A more fundamental limitation applies regardless of any convention, and no refinement of the screening model addresses it.')]));
B.push(p([t('H_cp is dimensionless. It is assembled from three integers. Deuteron–deuteron fusion, by contrast, proceeds through Coulomb barrier penetration, whose probability goes as exp(−G) where the Gamow factor G is built from the reduced mass in kilograms, the barrier height in joules, and the internuclear separation in metres. Converting a dimensionless lattice ratio into a rate requires a dimensional scale, and the framework supplies none.')]));
B.push(p([t('One might attempt to supply a scale from the physical geometry of the deuterium configuration — an interstitial separation of order 10⁻¹⁰ m, say. But the relevant separation for tunnelling is the distance of closest approach, some five orders of magnitude smaller, and any assumed relation between H_cp and that separation is precisely the physical content one is trying to derive. The exponential sensitivity of exp(−G) makes this fatal rather than merely imprecise.')]));
B.push(img('fig7_scalegap.png', 620, 226));
B.push(cap(7, 'The dimensional obstruction. (a) The lattice produces dimensionless quantities; barrier penetration requires dimensional ones, and the framework provides no bridge. (b) Sensitivity of the predicted Yb : Pd rate ratio to an assumed relation r_eff ∝ H_cp^(−p). Varying the exponent over a modest range moves the predicted ratio across twenty orders of magnitude. The prediction is a restatement of the assumption.'));
B.push(p([t('Figure 7(b) makes the point quantitatively. A ratio of roughly six in H_cp is compatible with a rate ratio of unity, or of 10²⁰, according to an exponent that nothing constrains. It follows that Part II cannot yield a falsifiable prediction in the ordinary sense: were ytterbium to show no anomalous behaviour whatever, no quantity in this framework would be contradicted, because none was ever committed to a magnitude.')]));
B.push(p([t('There is a further reason for caution. The three-body treatment in the exploratory work was motivated by the lattice having three axes. But (n, ℓ, k) are quantum numbers — a shell index, an angular momentum, a count — and their being three in number is not a statement about physical space. Reasoning from the dimensionality of the coordinate system to the geometry of a physical configuration conflates two distinct senses of "three-dimensional".')]));

B.push(h2('15.  What Part II Offers'));
B.push(p([t('Stripped of the claims it cannot support, the exploratory work leaves three things.')]));
B.push(p([t('First, a candidate-generation heuristic. The lattice, combined with two crystallographic filters, reduces 118 elements to nine and directs attention to a region of the periodic system that a palladium-centred literature has not systematically explored. Heuristics of this kind are legitimate and useful provided they are not mistaken for theories.')]));
B.push(p([t('Second, a specific and checkable observation. Ytterbium satisfies every practical criterion for a deuteride-loading host — FCC structure, established hydride chemistry, stability, availability — and appears absent from the experimental record. That absence is a fact about the literature, not a consequence of the index, and it would remain interesting if Equation (6) were discarded entirely.')]));
B.push(p([t('Third, a worked negative result. The dimensional obstruction of Section 14 is not peculiar to this framework; it applies to any scheme that attempts to reason from combinatorial or configuration-space quantities to nuclear rates. Documenting where the boundary lies has some value in a field with a long history of frameworks that did not identify their own.')]));

B.push(h2('16.  Conclusion'));
B.push(p([t('Part I offers a coordinate change and the structural facts it makes visible: a classification of the lattice\'s empty volume into void, reactive and reserved regimes, a census placing 92 cells in the last of these, a sorting of the elements into three geometric classes by the direction of ΔQ, and an adjacency between the late f-block and the late 5d metals that the conventional layout destroys. These results follow from the coordinates alone and do not depend on any dynamical interpretation of Equation (4).')]));
B.push(p([t('Part II applies that adjacency to deuteride host selection and returns a short candidate list in which ytterbium is the conspicuous entry. It also establishes, through Figures 6 and 7, that the ordering of that list is convention-dependent and that the framework cannot produce a rate prediction of any kind. The candidate list is offered on that basis: as a suggestion of where to look, made by a geometry that reorganises the elements usefully, and not as a claim about what will be found.')]));

