import eldata as ed
L=[(n,l,k) for n in range(1,8) for l in range(0,min(n,5)) for k in range(1,2*(2*l+1)+1)]
occ=set(ed.E[z] for z in ed.E)
def leq(a,b): return all(x<=y for x,y in zip(a,b))
# direct test: for every occupied x, is every admissible y <= x also occupied?
viol=[]
for x in occ:
    for y in L:
        if leq(y,x) and y not in occ:
            viol.append((y,x))
print("order-ideal violations:", len(viol))
for y,x in viol[:6]:
    print(f"   {y} ≤ {x} but {y} is unoccupied")
print()
print("So the earlier 'True' was a buggy generator expression (it short-circuits")
print("on an empty inner loop). The occupied set is NOT an order ideal.")
print()
# what IS it? measure how far from an ideal
need=set()
for x in occ:
    for y in L:
        if leq(y,x): need.add(y)
print(f"downward closure of the 118 occupied cells: {len(need)} cells")
print(f"of which occupied: {len(need & occ)}, unoccupied: {len(need - occ)}")
