from itertools import permutations, combinations
print("="*88)
print("INDEPENDENT VERIFICATION OF dim ≥ 3, BY EXHAUSTION ON THE WITNESS")
print("="*88)
A=[(7,2,6),(5,4,6),(5,2,8)]; B=[(5,4,8),(7,2,8),(7,4,6)]
P=A+B
def leq(a,b): return all(x<=y for x,y in zip(a,b))
rel={(x,y) for x in P for y in P if leq(x,y)}
print(f"  witness poset: {len(P)} elements")
print("  relation (x ≤ y) pairs, excluding reflexive:")
for x in P:
    ups=[y for y in P if leq(x,y) and x!=y]
    print(f"    {x} ≤ {ups if ups else '—'}")
def is_lin_ext(perm):
    pos={p:i for i,p in enumerate(perm)}
    return all(pos[x]<pos[y] for x,y in rel if x!=y)
LE=[p for p in permutations(P) if is_lin_ext(p)]
print(f"\n  linear extensions of the witness: {len(LE)}")
found=None; tested=0
for i in range(len(LE)):
    p1={p:j for j,p in enumerate(LE[i])}
    for k in range(i,len(LE)):
        p2={p:j for j,p in enumerate(LE[k])}
        tested+=1
        inter={(x,y) for x in P for y in P if p1[x]<=p1[y] and p2[x]<=p2[y]}
        if inter==rel: found=(LE[i],LE[k]); break
    if found: break
print(f"  pairs of linear extensions tested: {tested:,}")
if found:
    print(f"  *** A 2-REALIZER EXISTS — dim ≤ 2, the paper's claim FAILS ***")
    print(f"    {found[0]}\n    {found[1]}")
else:
    print(f"  no pair of linear extensions has the witness order as its intersection")
    print(f"  → dim(witness) ≥ 3, hence dim(Λ) ≥ 3.  INDEPENDENTLY CONFIRMED")
# and dim ≤ 3 by exhibiting a 3-realizer
print()
print("  Constructing a 3-realizer from the coordinate projections:")
import itertools as it
def proj_order(idx):
    return sorted(P,key=lambda c:(c[idx],c))
R=[{p:j for j,p in enumerate(proj_order(i))} for i in range(3)]
inter={(x,y) for x in P for y in P if all(r[x]<=r[y] for r in R)}
print(f"    intersection of the three coordinate orders equals the relation: {inter==rel}")
print(f"    → dim(witness) = 3 exactly")
EOF

