from itertools import combinations
CAP=lambda l:2*(2*l+1)
def leq(a,b): return all(x<=y for x,y in zip(a,b))
jn=lambda a,b: tuple(max(x,y) for x,y in zip(a,b))
mt=lambda a,b: tuple(min(x,y) for x,y in zip(a,b))
def closed(C):
    S=set(C)
    return not any(jn(a,b) not in S or mt(a,b) not in S for a,b in combinations(C,2))
# reduced base so the products stay computable
BASE=[(n,l,k) for n in range(1,5) for l in range(0,min(n,3)) for k in range(1,CAP(l)+1)]
print("="*92)
print("DO THE FOUR AXES COMPOSE?")
print("="*92)
print(f"  reduced base lattice (n ≤ 4, ℓ ≤ 2): {len(BASE)} cells, closed {closed(BASE)}")
def ext(C, kind):
    out=[]
    for c in C:
        n,l,k = c[0],c[1],c[2]
        if kind=='j':   rng=range(max(1,2*l-1),2*l+2,2)
        elif kind=='q': rng=range(0,k+1)
        elif kind=='S': rng=range(0,k+1)
        elif kind=='e': rng=range(n,6)
        for x in rng: out.append(c+(x,))
    return out
print(f"\n  {'lattice':<20}{'coords':>8}{'cells':>9}{'closed':>9}")
print("  "+"-"*48)
cur=BASE
print(f"  {'Λ':<20}{3:>8}{len(cur):>9}{str(closed(cur)):>9}")
seq=[('j','Λ_j'),('q','Λ_jq'),('S','Λ_jqS'),('e','Λ_jqSe')]
for kind,name in seq:
    cur=ext(cur,kind)
    if len(cur)>9000:
        print(f"  {name:<20}{len(cur[0]):>8}{len(cur):>9}{'too big':>9}"); break
    print(f"  {name:<20}{len(cur[0]):>8}{len(cur):>9}{str(closed(cur)):>9}")
print("""
  They compose. Each new axis is bounded monotonically in one of the ORIGINAL
  three coordinates, so adding one does not disturb the conditions the others
  satisfy, and the intersection of sublattices is a sublattice — the argument of
  §9.1 applied four times over.""")
print()
print("="*92)
print("DOES ADDING AN AXIS RAISE THE ORDER DIMENSION?")
print("="*92)
def has_S3(P):
    Ps=list(P)
    inc={x:{y for y in Ps if y!=x and not leq(x,y) and not leq(y,x)} for x in Ps}
    for a in Ps:
        for b in inc[a]:
            if b<=a: continue
            for c in inc[a]&inc[b]:
                if c<=b: continue
                A=(a,b,c); cand=[]; ok=True
                for jx in range(3):
                    need=[A[i] for i in range(3) if i!=jx]
                    cs=[x for x in Ps if leq(need[0],x) and leq(need[1],x) and not leq(A[jx],x)]
                    if not cs: ok=False; break
                    cand.append(cs)
                if not ok: continue
                for b0 in cand[0]:
                    for b1 in cand[1]:
                        if b1==b0: continue
                        for b2 in cand[2]:
                            if b2 in (b0,b1): continue
                            if len({b0,b1,b2}|set(A))==6: return True
    return False
print("""  Λ ⊆ ℤ³ gives dim ≤ 3 and the S₃ witness gives dim = 3. A four-coordinate
  extension sits in ℤ⁴ so dim ≤ 4. Is it 4, or does it stay at 3?""")
for kind,name in [('j','Λ_j'),('q','Λ_q'),('S','Λ_S'),('e','Λ_e')]:
    C=ext(BASE,kind)
    print(f"    {name:<6} {len(C):>5} cells   contains S₃: {has_S3(C)}   → dim ≥ 3, ≤ 4")
EOF

